9	/**
10	 * Admin power-tools for finance ops: refunds, manual balance adjustments and
11	 * bulk invoice/client actions. Every action is gated by `requireArea("billing")`
12	 * (bulk-suspend is ADMIN-only, matching `adminSetUserSuspended`) and writes an
13	 * AuditLog row.
14	 *
15	 * The existing single-invoice void / mark-paid live in `lib/actions-billing.ts`
16	 * and are consumed directly from there (a "use server" file cannot re-export).
17	 */
18	
19	async function audit(userId: string | null, action: string, detail?: string) {
20	  await db.auditLog.create({ data: { userId, action, detail } });
21	}
