345	  ids: string[]
346	): Promise<{ suspended: number }> {
347	  const admin = await requireAdmin();
348	  const unique = [...new Set((ids ?? []).filter(Boolean))]
349	    .filter((id) => id !== admin.id)
350	    .slice(0, 500);
351	  if (unique.length === 0) return { suspended: 0 };
352	
353	  const res = await db.user.updateMany({
354	    where: { id: { in: unique }, role: { not: "ADMIN" } },
355	    data: { suspended: true },
356	  });
357	
358	  await audit(admin.id, "clients.bulk_suspend", `${res.count} suspended`);
359	  revalidatePath("/admin/users");
360	  return { suspended: res.count };
361	}
