3	// Server actions behind the "card on file" section of the customer billing page.
4	//
5	// The whole flow is redirect-based (Stripe hosted Checkout in `mode: "setup"`),
6	// because no Stripe Elements / Stripe.js integration exists in this codebase and
7	// no publishable key is plumbed to the browser. That means there is a moment where
8	// the card exists at Stripe and not here, which is exactly the shape of the
9	// fulfilment bug that cost a customer their server once already — see
10	// `adoptUnclaimedCards` in `lib/stripe-cards.ts` for the backstop.
11	//
12	// ROUTE NOTE: `app/api/stripe/**` is owned elsewhere, so the return leg is NOT an
13	// API route. Stripe redirects to `/dashboard/billing?card_setup=<session_id>` and
14	// a small client component calls `finalizeCardSetup` below. If a route is wanted
15	// later, the natural one is `GET /api/stripe/setup-return?session_id=…` calling
16	// `saveCardFromSetupSession(sessionId, currentUser().id)` and redirecting to
17	// `/dashboard/billing?card=saved`.
18	
19	import { revalidatePath } from "next/cache";
20	import { db } from "./db";
21	import { requireUser, assertNotImpersonating } from "./auth";
22	import { stripeConfigured } from "./stripe";
23	import { walletSplit } from "./wallet-split";
