40	/**
41	 * Begin saving a card. Returns the hosted Checkout URL for the browser to follow.
42	 *
43	 * The `card.setup_started` audit row is not just bookkeeping: it is the evidence
44	 * `adoptUnclaimedCards` requires before it will adopt a card that is attached at
45	 * Stripe but was never confirmed here, which is what keeps a REMOVED card from
46	 * being silently resurrected.
47	 */
48	export async function startCardSetup(): Promise<{ url?: string; error?: string }> {
49	  // An admin impersonating a customer must not be able to put a card on their
50	  // account — the same reasoning that blocks impersonated wallet spend.
51	  await assertNotImpersonating();
52	  const user = await requireUser();
53	  if (!stripeConfigured()) {
54	    return { error: "Card payments aren't configured on this installation yet." };
55	  }
56	  try {
57	    const url = await createCardSetupSession(user);
58	    if (!url) return { error: "Stripe didn't return a setup link. Please try again." };
59	    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
60	    return { url };
61	  } catch (e) {
62	    console.error("[payment-method] setup session failed", e);
63	    return { error: "We couldn't start card setup just now. Please try again in a moment." };
64	  }
