121	/**
122	 * Mint a FRESH hosted-Checkout link for a server's outstanding renewal balance.
123	 *
124	 * A link is minted on demand rather than reusing the stored `dunningPayUrl`
125	 * because Stripe Checkout sessions expire within 24 hours while the dunning
126	 * sequence runs for six days — surfacing the stored link in the portal would show
127	 * an expired Stripe page to a customer trying to pay us.
128	 */
129	export async function settleOutstanding(
130	  serverId: string,
131	): Promise<{ url?: string; error?: string; covered?: boolean }> {
132	  const user = await requireUser();
133	  if (!stripeConfigured()) {
134	    return { error: "Card payments aren't configured — add funds to your wallet instead." };
135	  }
136	  const server = await db.server.findUnique({
137	    where: { id: serverId },
138	    include: { plan: true, gamePlan: true, dedicatedIp: true, user: true },
139	  });
140	  if (!server) return { error: "Server not found." };
141	  if (server.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden" };
142	  if (server.isFree || !server.expiresAt) return { error: "This server has nothing outstanding." };
143	
144	  // EVERY figure below is the OWNER's, never the caller's.
145	  //
146	  // The admin branch above lets staff mint this link on a customer's behalf, and
147	  // until now the split was computed from `user.balanceCents` and the session was
148	  // stamped with `user.id` — the ADMIN's wallet and the ADMIN's account. So an
149	  // admin settling a customer's balance quoted a remainder against their own
150	  // credit and produced a Checkout session whose payment credits the admin's
151	  // wallet, leaving the customer's server exactly as unpaid as before. Worse, the
152	  // link is stored on `Server.dunningPayUrl` and `worker/billing.ts` reuses a
153	  // stored link verbatim in the "your bank needs to confirm" email — so the
154	  // CUSTOMER would be emailed a page that pays money into someone else's wallet.
155	  // The balance belongs to the server's owner, so the whole quote does.
156	  const owner = server.user;
157	  const charge = renewalCharge(server, {
158	    ipMonthlyCents: await dedicatedIpMonthlyCents(),
159	    extraDiskPerGbCents: await extraDiskPerGbCents(),
160	    backupPlusCents: await backupPlusMonthlyCents(),
161	    annualDiscountPct: await annualDiscountPct(),
162	  });
163	  // Wallet credit first, card for the remainder — the same split the sweep will
164	  // apply, so the quote here and the charge there can never disagree.
165	  const split = walletSplit({
166	    dueCents: charge.totalCents,
167	    balanceCents: owner.balanceCents,
168	    useWallet: true,
169	  });
170	  if (split.cardCents === 0) {
171	    return {
172	      covered: true,
173	      error:
174	        server.userId === user.id
175	          ? "Your wallet already covers this renewal — it completes automatically within a few minutes."
176	          : "This customer's wallet already covers the renewal — it completes automatically within a few minutes.",
177	    };
178	  }
179	
180	  const url = await createOutstandingCheckout({
181	    user: owner,
182	    amountCents: split.cardCents,
183	    hostname: server.hostname,
184	    serverId: server.id,
185	  });
186	  if (!url) return { error: "We couldn't start checkout just now. Please try again in a moment." };
187	  // Keep the stored link current for the dunning emails and admin visibility.
188	  await db.server.update({ where: { id: server.id }, data: { dunningPayUrl: url } });
189	  return { url };
190	}
