48	/**
49	 * Permanently delete the caller's own account.
50	 *
51	 * Guard: the user must type their exact email, and must have NO active server
52	 * (any server with a status other than DELETING). They have to delete their
53	 * servers first — we refuse otherwise so no live VM is orphaned.
54	 *
55	 * The `User` row is removed inside a transaction. Relations that don't cascade
56	 * at the DB level (servers, wallet transactions, audit logs, referrals) are
57	 * cleaned up manually first; the rest cascade from `user.delete`. The deletion
58	 * is audit-logged with `userId: null` before the user disappears.
59	 */
60	export async function deleteMyAccount(confirmEmail: string): Promise<{ error?: string }> {
61	  const user = await requireUser();
62	
63	  const typed = (confirmEmail ?? "").trim().toLowerCase();
64	  if (!typed) return { error: "Type your email to confirm." };
65	  if (typed !== user.email.toLowerCase()) {
66	    return { error: "That email doesn't match your account." };
67	  }
68	
69	  const active = await activeServerCount(user.id);
70	  if (active > 0) {
71	    return {
72	      error: `You still have ${active} active server${active === 1 ? "" : "s"}. Delete ${
73	        active === 1 ? "it" : "them"
74	      } first, then close your account.`,
75	    };
76	  }
77	
78	  // A server in DELETING still has a real VM on the hypervisor until its worker
79	  // DELETE job completes. If we removed the row now, the cascade would delete that
80	  // in-flight job too and orphan the VM forever (running + billing, unreachable).
81	  // Refuse until teardown finishes — the user retries in a minute.
82	  const tearingDown = await db.server.count({ where: { userId: user.id, status: "DELETING" } });
83	  if (tearingDown > 0) {
84	    return {
85	      error: `${tearingDown} server${tearingDown === 1 ? " is" : "s are"} still being torn down. Wait a moment for that to finish, then close your account.`,
86	    };
87	  }
88	
89	  await db.$transaction([
90	    // Record the deletion with no owning user (survives the cascade).
91	    db.auditLog.create({
92	      data: {
93	        userId: null,
94	        action: "user.account_deleted",
95	        detail: `${user.email} (${user.id}) — self-service GDPR deletion`,
96	      },
97	    }),
98	    // AuditLog.user has no cascade: anonymize this user's remaining trail.
99	    db.auditLog.updateMany({ where: { userId: user.id }, data: { userId: null } }),
100	    // Self-relation has no cascade: detach anyone this user referred.
101	    db.user.updateMany({ where: { referredById: user.id }, data: { referredById: null } }),
102	    // WalletTransaction.user has no cascade.
103	    db.walletTransaction.deleteMany({ where: { userId: user.id } }),
104	    // Server.user has no cascade. Past the guard only DELETING rows remain;
105	    // removing them cascades jobs, port forwards, dedicated IPs, claude builds, etc.
106	    db.server.deleteMany({ where: { userId: user.id } }),
107	    // PasswordResetToken has no FK relation — hygiene only.
108	    db.passwordResetToken.deleteMany({ where: { userId: user.id } }),
109	    // Cascades: projects, ssh keys, tickets, notifications, domains, invoices,
110	    // api tokens, memberships, owned orgs, coupon redemptions; feedback & gift
111	    // codes are set-null by the schema.
112	    db.user.delete({ where: { id: user.id } }),
113	  ]);
114	
115	  await destroySession();
116	  redirect("/");
117	}
