3	// Server actions for the native Nxeon Calendar + Tasks feature
4	// (/dashboard/calendar).
5	//
6	// Every action authenticates the caller (`requireUser`, via `resolveMailbox`),
7	// resolves ONLY a mailbox the caller owns, decrypts its stored credential, and
8	// talks to the customer's SOGo CalDAV over the mail server — reusing the SAME
9	// per-user mailbox credential the webmail client uses. Mutating actions are
10	// rate-limited and validate their input. The password never leaves the server.
11	//
12	// Signatures are fixed by lib/calendar/types.ts — the UI builds against the same
13	// contract, so do not change them here.
14	
15	import { resolveMailbox } from "@/lib/mail/imap";
16	import { checkRateLimit, type RateLimitOptions } from "@/lib/rate-limit";
17	import type {
18	  CalEvent,
19	  CalendarInfo,
20	  EventInput,
21	  TaskInput,
22	  TaskItem,
23	} from "@/lib/calendar/types";
24	import {
25	  caldavClient,
26	  deleteObjectAt,
27	  fetchCalendars,
28	  fetchEventObjects,
29	  fetchObjectByUrl,
30	  fetchTaskObjects,
31	  putObject,
32	  putObjectAt,
33	} from "@/lib/calendar/caldav";
34	import {
35	  buildEventICS,
36	  buildTaskICS,
37	  newUID,
38	  parseCalEvents,
39	  parseTaskItems,
40	  setTaskCompletedInICS,
