42	      userId: user.id,
43	      kind: parsed.data.kind,
44	      title: parsed.data.title,
45	      body: parsed.data.body,
46	      url: parsed.data.url && parsed.data.url.length > 0 ? parsed.data.url : null,
47	    },
48	  });
49	
50	  // Ping staff so triage sees it.
