1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { headers } from "next/headers";
5	import { requireUser } from "./auth";
6	import { clientIp } from "./rate-limit";
7	import { sendVerificationEmail, isEmailVerified } from "./email-verification";
8	
9	export type ResendState = { ok?: boolean; error?: string; message?: string };
10	
11	/**
12	 * Re-send the verification link to the signed-in account's own address.
13	 *
14	 * Note what this action does NOT accept: an address. It only ever mails
15	 * `user.email`, read from the session on the server. An action that took an
16	 * address parameter would be an open relay pointed at our own domain — anyone
17	 * with an account could have Nxeon-branded mail delivered to a stranger.
18	 *
19	 * Throttled per user AND per source IP: the per-user key stops one account
20	 * hammering one mailbox, and the per-IP key stops one script cycling through
21	 * many fresh accounts to do the same thing at scale.
22	 *
23	 * The address comes from `clientIp`, not from the first entry of
24	 * `x-forwarded-for`. That entry is written by the client, so composing it into
25	 * the key handed the SENDER control of their own throttle: a different fake
26	 * value per request is a different bucket per request, and "5 links an hour"
27	 * became unlimited. This platform's mail is currently unsigned (no DKIM), so an
28	 * uncapped send loop does not just annoy one mailbox — it is the fastest way to
29	 * get the whole domain classified as a spam source.
30	 */
31	export async function resendVerificationEmail(): Promise<ResendState> {
32	  const user = await requireUser();
33	  if (isEmailVerified(user)) {
34	    return { ok: true, message: "That address is already confirmed." };
35	  }
36	  const ip = clientIp(await headers());
37	  const outcome = await sendVerificationEmail(user, { throttleKey: `${user.id}:${ip}` });
38	  switch (outcome) {
39	    case "sent":
40	      return { ok: true, message: `Sent. Check ${user.email} — the link is good for 24 hours.` };
41	    case "already_verified":
42	      return { ok: true, message: "That address is already confirmed." };
43	    case "rate_limited":
44	      return {
45	        error:
46	          "We've sent several links already. Check your spam folder, then try again in an hour — or open a support ticket and we'll sort it out with you.",
47	      };
48	    default:
49	      // Never pretend a send worked. The whole B4 defect class is a screen that
50	      // reports success while nothing happened.
51	      return { error: "We couldn't send that email just now. Please try again shortly, or contact support." };
52	  }
53	}
54	
55	/** Form-action wrapper for `useActionState`. */
56	export async function resendVerificationAction(_prev: ResendState): Promise<ResendState> {
57	  const res = await resendVerificationEmail();
58	  revalidatePath("/dashboard");
59	  return res;
60	}
