266	      ramTotal: s?.memory?.total,
267	      ramUsed: s?.memory?.used,
268	      cpu: typeof s?.cpu === "number" ? s.cpu : undefined,
269	      pveVersion: typeof s?.pveversion === "string" ? s.pveversion : undefined,
270	      checkedAt,
271	    };
272	  } catch (e: any) {
273	    await db.node.update({
274	      where: { id },
275	      data: { status: node.status === "MAINTENANCE" ? "MAINTENANCE" : "OFFLINE" },
276	    });
277	    await audit(admin.id, "node.test.fail", `${node.name}: ${String(e?.message ?? e).slice(0, 160)}`);
278	    revalidatePath("/admin/nodes");
279	    revalidatePath(`/admin/nodes/${id}`);
280	    return { ok: false, message: `Unreachable: ${String(e?.message ?? e).slice(0, 200)}`, checkedAt };
