3	/**
4	 * Control panel — Cron jobs & Services.
5	 *
6	 * Cron: add/edit/remove crontab entries (rendered into one Nxeon-managed block
7	 * on the VPS by worker/services.ts on CRON_SYNC).
8	 * Services: start/stop/restart nginx/php-fpm/mysql/docker/… (worker SERVICE_ACTION),
9	 * plus inline reads for service status and a live process/resource snapshot
10	 * (lib/cpanel-inline.ts — sandbox-synthetic on staging, short-timeout SSH on prod).
11	 */
12	import { revalidatePath } from "next/cache";
13	import { db } from "./db";
14	import { requireUser } from "./auth";
15	import { checkRateLimit } from "./rate-limit";
16	import { assertCronSchedule } from "./ssh-exec";
17	import { readServiceStatuses, readProcessSnapshot } from "./cpanel-inline";
18	import {
19	  COMMON_SERVICES,
20	  SERVICE_ACTIONS,
21	  type CronRow,
22	  type ServiceStatus,
23	  type ProcessSnapshot,
24	} from "./cpanel-types";
25	import type { SftpServer } from "./sftp";
26	
27	type Result = { ok: true } | { ok: false; error: string };
28	type CreateResult = { ok: true; id: string } | { ok: false; error: string };
29	
30	const EXCLUSIVE_JOBS = [
31	  "PROVISION",
32	  "REINSTALL",
33	  "DELETE",
34	  "RESIZE",
35	  "SUSPEND",
36	  "UNSUSPEND",
37	  "SNAPSHOT_ROLLBACK",
38	  "BACKUP_RESTORE",
39	  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
40	  // control-panel operations out of the way while the root filesystem is resized.
41	  "DISK_EXPAND",
42	] as const;
43	
44	/** Max length for a cron command line. */
45	const MAX_CMD_LEN = 500;
46	
47	async function ownedServer(serverId: string) {
48	  const user = await requireUser();
49	  const server = await db.server.findUnique({
50	    where: { id: serverId },
51	    select: {
52	      id: true,
53	      userId: true,
54	      status: true,
55	      hostname: true,
56	      rootPassword: true,
57	      rootPasswordEnc: true,
58	      sshPort: true,
59	      dedicatedIp: { select: { address: true } },
60	    },
61	  });
62	  if (!server) throw new Error("Not found");
63	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
64	  return { user, server };
65	}
66	
67	async function ownedCron(id: string) {
68	  const user = await requireUser();
69	  const cron = await db.cronJob.findUnique({ where: { id } });
70	  if (!cron) throw new Error("Not found");
71	  if (cron.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
72	  return { user, cron };
73	}
74	
75	function throttle(userId: string, op: string, max: number): string | null {
76	  const rl = checkRateLimit(`cpanel:cron:${op}:${userId}`, { max, windowMs: 60_000 });
77	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
78	}
79	
80	async function lifecycleBusy(serverId: string): Promise<boolean> {
81	  const n = await db.job.count({
82	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
83	  });
84	  return n > 0;
85	}
86	
87	function safeError(err: unknown): string {
88	  const msg = err instanceof Error ? err.message : String(err);
89	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
90	  if (/timed out|reachable|root password|package manager/i.test(msg)) return msg.slice(0, 200);
91	  if (/^Unsupported |cron/i.test(msg)) return msg.slice(0, 200);
92	  return "Could not reach the server. Please try again shortly.";
93	}
94	
95	/**
96	 * Validate a cron command: length-bounded, no NUL / newline / control chars, no
97	 * comment-injection into the crontab block. The command is written to the far
98	 * side via a here-doc body (STDIN), never interpolated into a shell command, so
99	 * shell metacharacters inside it run in the user's OWN crontab as intended — but
100	 * we still forbid newlines (would forge extra crontab lines).
101	 */
102	function validateCommand(cmd: string): string {
103	  const c = String(cmd ?? "");
104	  if (c.trim().length === 0) throw new Error("A command is required.");
105	  if (c.length > MAX_CMD_LEN) throw new Error(`Command is too long (max ${MAX_CMD_LEN} chars).`);
106	  if (/[\x00-\x08\x0a-\x1f\x7f]/.test(c)) throw new Error("Command contains invalid control characters.");
107	  return c.trim();
108	}
109	
110	function rowOut(c: {
111	  id: string;
112	  schedule: string;
113	  command: string;
114	  comment: string | null;
115	  enabled: boolean;
116	  status: string;
117	  error: string | null;
118	  createdAt: Date;
119	}): CronRow {
120	  return {
121	    id: c.id,
122	    schedule: c.schedule,
123	    command: c.command,
124	    comment: c.comment,
125	    enabled: c.enabled,
126	    status: c.status,
127	    error: c.error,
128	    createdAt: c.createdAt.toISOString(),
129	  };
130	}
