1	/**
2	 * Short-lived, encrypted authorization tokens for the in-portal web terminal.
3	 *
4	 * The browser never opens the terminal websocket with its session cookie —
5	 * instead the app mints a 60-second, single-purpose token (this module) that
6	 * encodes exactly {userId, serverId}. The standalone PTY backend
7	 * (terminal-server/index.ts) verifies that token before it will SSH anywhere.
8	 *
9	 * The token is a JWE (encrypted, A256GCM) — mirroring the VNC console ticket in
10	 * app/api/console/[serverId]/route.ts — so its contents are opaque to the
11	 * browser and cannot be tampered with. The symmetric key is DERIVED from the
12	 * app's AUTH_SECRET the same way the console does, with a terminal-specific
13	 * salt, so the web app and the terminal backend agree on the key with no extra
14	 * shared secret to configure.
15	 *
16	 * Plain server-side module (no "use server"): importable by both the Next route
17	 * handler and the tsx-run terminal backend.
18	 */
19	import { createHash } from "node:crypto";
20	import { EncryptJWT, jwtDecrypt } from "jose";
21	
22	/** Lifetime of a minted terminal token. It only needs to survive the round-trip
23	 * from `POST /api/terminal/token` to the websocket upgrade. */
24	export const TERMINAL_TOKEN_TTL_SECONDS = 60;
25	
26	/** What every terminal token carries. Nothing sensitive — just who + which VM. */
27	export type TerminalTokenClaims = {
28	  userId: string;
29	  serverId: string;
30	};
31	
32	/**
33	 * 256-bit symmetric key for the terminal JWE, derived from AUTH_SECRET. The
34	 * terminal backend derives the identical key the same way, so no separate
35	 * secret needs distributing. Distinct salt from the console key so a console
36	 * ticket can never be replayed as a terminal token (or vice-versa).
37	 */
38	function terminalKey(): Uint8Array {
39	  const secret = process.env.AUTH_SECRET;
40	  if (!secret) throw new Error("AUTH_SECRET is not set");
41	  return new Uint8Array(createHash("sha256").update(`nxeon-terminal:${secret}`).digest());
42	}
43	
44	/** Mint an encrypted, 60-second terminal token for {userId, serverId}. */
45	export async function signTerminalToken(claims: TerminalTokenClaims): Promise<string> {
46	  return new EncryptJWT({ userId: claims.userId, serverId: claims.serverId })
47	    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
48	    .setIssuedAt()
49	    .setExpirationTime(`${TERMINAL_TOKEN_TTL_SECONDS}s`)
50	    .encrypt(terminalKey());
51	}
52	
53	/**
54	 * Verify + decrypt a terminal token. Returns the claims, or throws if the token
55	 * is missing, malformed, tampered with, or expired (jwtDecrypt enforces `exp`).
56	 */
57	export async function verifyTerminalToken(token: string): Promise<TerminalTokenClaims> {
58	  const { payload } = await jwtDecrypt(token, terminalKey());
59	  const userId = payload.userId;
60	  const serverId = payload.serverId;
61	  if (typeof userId !== "string" || typeof serverId !== "string" || !userId || !serverId) {
62	    throw new Error("terminal token missing userId/serverId");
63	  }
64	  return { userId, serverId };
65	}
