150	/**
151	 * Derive the passwordless lift-and-shift plan from the read-only scan and the set
152	 * of paths the customer chose to copy. Databases are auto-included whenever an
153	 * engine was detected (no password needed — the worker dumps via root's local
154	 * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
155	 * can install them on the target. Everything here is secret-free.
156	 */
157	function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
158	  const empty: MigrationPlan = {
159	    dbEngines: [],
160	    dockerVolumes: [],
161	    composeDirs: [],
162	    verifyPorts: [],
163	    hasContainers: false,
164	    webServers: [],
165	    runtimes: [],
166	  };
167	  if (!scan || !scan.ok) return empty;
168	  const pathSet = new Set(selectedPaths);
169	
170	  // Auto-include every detected engine (dump passwordlessly via root local auth).
171	  const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
172	    (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
173	  );
174	
175	  const containers = scan.containers ?? [];
176	  // Named Docker volumes = container mounts that are NOT absolute host paths.
177	  const dockerVolumes = [
178	    ...new Set(
179	      containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
180	    ),
181	  ].slice(0, 60);
182	
183	  // Compose project dirs among the app dirs the customer is actually copying.
184	  const composeDirs = [
185	    ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
186	  ].slice(0, 40);
187	
188	  // Ports we will hold the migration accountable for. ONLY the customer's own
189	  // services — never the base operating system's.
190	  //
191	  // This used to be every listening port on the source except 22, so a stock
192	  // Debian box handed the customer `25` (exim4, installed by the distro and never
193	  // configured), `5355` (systemd-resolved's mDNS stub) and `53` as "not up on the
194	  // target yet — start the owning app/service". Those are not the customer's
195	  // software, were never part of what they asked to move, and cannot be started
196	  // by them in any meaningful sense. Seven of twenty-two action items in the
197	  // 2026-07-26 rehearsal were this noise, which is how a real action item gets
198	  // lost: a list that cries wolf is a list nobody reads to the end of.
199	  //
200	  // Filtering by PORT NUMBER would be the wrong fix — a customer really can run
201	  // their own mail server on 25. The honest discriminator is the OWNING PROCESS,
202	  // which the scan already captured, so a port is dropped only when the thing
203	  // listening on it is a distro daemon we did not migrate.
204	  const OS_DAEMONS =
205	    /^(systemd-resolve|systemd-resolved|systemd-network|exim4?|sendmail|postfix|rpcbind|rpc\.statd|avahi-daemon|cupsd|chronyd?|ntpd|dhclient|dhcpcd|named|dnsmasq|snapd|multipathd|master)$/i;
206	  const verifyPorts = [
207	    ...new Set(
208	      (scan.ports ?? [])
209	        .filter((p) => {
210	          if (!Number.isInteger(p.port) || p.port < 1 || p.port > 65535 || p.port === 22) return false;
211	          // No owning process recorded: keep it. An unknown is reported, never
212	          // silently dropped — that is the mistake this whole engine exists to
213	          // stop making.
214	          const proc = (p.proc || "").trim().toLowerCase();
215	          if (!proc) return true;
216	          return !OS_DAEMONS.test(proc);
217	        })
218	        .map((p) => p.port)
219	    ),
220	  ].slice(0, 60);
221	
222	  const hasContainers = containers.length > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
223	
224	  // Web servers: match the owning process/service names, else default to nginx
225	  // when web roots exist (the overwhelmingly common case).
226	  const procBlob = [
227	    ...(scan.ports ?? []).map((p) => p.proc || ""),
228	    ...(scan.services ?? []).map((s) => s.name || ""),
229	  ]
230	    .join(" ")
231	    .toLowerCase();
232	  const webServers: ("nginx" | "apache")[] = [];
233	  if (/nginx/.test(procBlob)) webServers.push("nginx");
234	  if (/apache|httpd/.test(procBlob)) webServers.push("apache");
235	  if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");
236	
237	  // Runtimes: from running-app runtimes and listening-port owners. Conservative.
238	  const runtimeBlob = [
239	    ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
240	    ...(scan.ports ?? []).map((p) => p.proc || ""),
241	  ]
242	    .join(" ")
243	    .toLowerCase();
244	  const runtimes: ("nodejs" | "python3")[] = [];
245	  if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
246	  if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");
247	
248	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
249	}
