287	/** Parse ID / VERSION_ID / PRETTY_NAME lines from `/etc/os-release` (never sourced). */
288	function parseOsRelease(stdout: string): { id: string; versionId: string; pretty: string } | null {
289	  const o: Record<string, string> = {};
290	  for (const line of (stdout ?? "").split("\n")) {
291	    const m = /^(ID|VERSION_ID|PRETTY_NAME)=(.*)$/.exec(line.trim());
292	    if (!m) continue;
293	    o[m[1]] = m[2].trim().replace(/^["']|["']$/g, "").slice(0, 128);
294	  }
295	  if (!o.ID && !o.PRETTY_NAME && !o.VERSION_ID) return null;
296	  return {
297	    id: (o.ID ?? "").toLowerCase().slice(0, 32),
298	    versionId: (o.VERSION_ID ?? "").slice(0, 32),
299	    pretty: o.PRETTY_NAME ?? "",
300	  };
301	}
