303	/**
304	 * Validate a customer-named SOURCE host and resolve it to a vetted PUBLIC
305	 * address.
306	 *
307	 * This module's whole job is to SSH, from inside the platform, into a machine
308	 * whose address, username and password the customer types into a form. `HOST_RE`
309	 * checked only that the string looked like a host — so `10.20.0.137`,
310	 * `127.0.0.1` and the Proxmox host's own address all passed. That made the
311	 * migration wizard three things it was never meant to be:
312	 *
313	 *   - an internal PORT SCANNER of 10.20.0.0/24, which is every other customer's
314	 *     VPS, distinguishable because `scanSource` reports "couldn't sign in"
315	 *     (something is listening and speaking SSH) separately from "couldn't reach"
316	 *     (nothing there);
317	 *   - an SSH CREDENTIAL-STUFFING engine against those same machines, since the
318	 *     password is supplied per attempt;
319	 *   - a way to point it at the hypervisor and the platform's own loopback.
320	 *
321	 * A real migration source is always a public IP at another provider, so refusing
322	 * private / loopback / link-local / reserved targets costs a legitimate customer
323	 * nothing. `resolvePublicHost` (lib/tools/net-guard.ts) also resolves the name
324	 * itself and rejects if ANY A/AAAA record is private, which closes the DNS
325	 * rebinding variant — a name that answers public on our check and private on the
326	 * connect. The vetted address is returned so the caller can connect to the IP we
327	 * actually checked rather than re-resolving.
328	 */
329	async function vettedSourceHost(
330	  raw: string | undefined,
331	): Promise<{ host: string; address: string } | { error: string }> {
332	  const host = (raw ?? "").trim();
333	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
334	    return { error: "Enter a valid source host — an IP address or domain name." };
335	  }
336	  try {
337	    const resolved = await resolvePublicHost(host);
338	    return { host, address: resolved.addresses[0] ?? host };
339	  } catch (e) {
340	    if (e instanceof BlockedHostError) {
341	      return {
342	        error:
343	          `We can't migrate from ${host}: ${e.message} ` +
344	          `The source has to be a server reachable on the public internet — use its public IP address ` +
345	          `or a domain name that points at it, not a private/LAN address.`,
346	      };
347	    }
348	    return {
349	      error:
350	        `We couldn't look up ${host}. Check the spelling, or enter the source server's public IP address instead.`,
351	    };
352	  }
353	}
