355	async function ownedTargetServer(serverId: string) {
356	  const user = await requireUser();
357	  const server = await db.server.findUnique({ where: { id: serverId } });
358	  if (!server) throw new Error("Not found");
359	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
360	  return { user, server };
