372	/**
373	 * READ-ONLY pre-flight for consolidating several source servers onto one target.
374	 * Builds each source's resource inventory from its scan, runs the pure collision
375	 * planner (lib/migrate-consolidate.ts) and returns the auto-remap plan for the
376	 * operator to approve. No writes, no SSH, no engine work — just the plan. The
377	 * actual sequential migrations (which carry each remap in Migration.items) and
378	 * the engine-side application of the remap are the execution half, kept separate
379	 * so this preview can never mutate anything.
380	 */
381	export async function planConsolidationMigration(input: {
382	  serverId: string;
383	  sources: ConsolidationSourceInput[];
384	}): Promise<{ error?: string; plan?: ConsolidationPlan }> {
385	  const { user, server } = await ownedTargetServer(input.serverId);
386	  void server;
387	  if (!Array.isArray(input.sources) || input.sources.length < 2) {
388	    return { error: "Add at least two source servers to consolidate." };
389	  }
390	  if (input.sources.length > 10) {
391	    return { error: "You can consolidate up to 10 servers at a time." };
392	  }
393	  const rl = checkRateLimit(`migrate:consolidate-plan:${user.id}`, { max: 20, windowMs: 10 * 60 * 1000 });
394	  if (!rl.ok) return { error: `Slow down — try again in ${rl.retryAfterSec}s.` };
395	
396	  const inventories = input.sources.map((s) =>
397	    inventoryFromScan(String(s.label || s.host).slice(0, 40), String(s.host).slice(0, 253), {
398	      scan: {
399	        ports: s.scan.ports ?? [],
400	        appDirs: [
401	          ...(s.scan.appDirs ?? []).map((d) => ({ path: d.path })),
402	          ...(s.scan.webRoots ?? []).map((w) => ({ path: w.path })),
403	          ...(s.scan.homes ?? []).map((h) => ({ path: h.path })),
404	        ],
405	        containers: (s.scan.containers ?? []).map((c) => ({ mounts: c.mounts })),
406	      },
407	      items: { databases: (s.scan.databases ?? []).map((d) => ({ name: d.name })) },
408	      domains: s.domains ?? [],
409	    }),
410	  );
411	
412	  // Fresh targets have nothing yet; when consolidating onto a box that already
413	  // runs apps, its inventory would seed the "used" sets here (future: scan target).
414	  const plan = planConsolidation(inventories, {});
415	  return { plan };
416	}
