418	export type ConsolidationStartSource = Omit<CreateMigrationInput, "serverId"> & { label?: string; domains?: string[] };
419	
420	function inventoriesForSources(sources: ConsolidationStartSource[]) {
421	  return sources.map((s, i) =>
422	    inventoryFromScan(String(s.label || s.sourceHost || `src-${i + 1}`).slice(0, 40), String(s.sourceHost).slice(0, 253), {
423	      scan: {
424	        ports: s.scan?.ports ?? [],
425	        appDirs: [
426	          ...(s.scan?.appDirs ?? []).map((d) => ({ path: d.path })),
427	          ...(s.scan?.webRoots ?? []).map((w) => ({ path: w.path })),
428	          ...(s.scan?.homes ?? []).map((h) => ({ path: h.path })),
429	        ],
430	        containers: (s.scan?.containers ?? []).map((c) => ({ mounts: c.mounts })),
431	      },
432	      items: { databases: (s.scan?.databases ?? []).map((d) => ({ name: d.name })) },
433	      domains: s.domains ?? [],
434	    }),
435	  );
