438	/**
439	 * Consolidate several source servers onto ONE target. Builds the collision plan
440	 * and REFUSES (returning the blockers) when sources overlap on ports or paths —
441	 * those need the verified engine remap step before they can auto-run without risk
442	 * of one app clobbering another. When there are no such blockers, it creates a
443	 * migration per source; the serial worker imports them one after another onto the
444	 * same target. Domain overlaps are allowed (you point DNS where you choose).
445	 */
446	export async function startConsolidationMigration(input: {
447	  serverId: string;
448	  sources: ConsolidationStartSource[];
449	}): Promise<{ error?: string; ids?: string[]; blockers?: Collision[]; plan?: ConsolidationPlan }> {
450	  const { user } = await ownedTargetServer(input.serverId);
451	  if (!Array.isArray(input.sources) || input.sources.length < 2) {
452	    return { error: "Add at least two source servers to consolidate." };
453	  }
454	  if (input.sources.length > 5) {
455	    return { error: "You can consolidate up to 5 servers at a time." };
456	  }
457	  const rl = checkRateLimit(`migrate:consolidate:${user.id}`, { max: 3, windowMs: 30 * 60 * 1000 });
458	  if (!rl.ok) return { error: `Slow down — try again in ${rl.retryAfterSec}s.` };
459	
460	  const plan = planConsolidation(inventoriesForSources(input.sources), {});
461	  const blockers = consolidationBlockers(plan);
462	  const portBlk = blockers.filter((b) => b.kind === "port");
463	  const pathBlk = blockers.filter((b) => b.kind === "path");
464	  const ex = (arr: Collision[]) => [...new Set(arr.map((b) => b.value))].slice(0, 3).join(", ");
465	
466	  // Port overlaps can never auto-resolve: two apps cannot share a port, and the
467	  // app's own bind config is not ours to guess. Always block.
468	  if (portBlk.length) {
469	    return { error: `These servers overlap on ports (${ex(portBlk)}). Two apps can't share a port — change one at the source, then consolidate.`, blockers, plan };
470	  }
471	  // Path overlaps: the engine copies each colliding path to its OWN directory (no
472	  // data loss), then reports where it landed so you point the app's config there.
473	  // Gated behind NXEON_CONSOLIDATE_REMAP until validated on a migration rehearsal.
474	  const remapEnabled = !!process.env.NXEON_CONSOLIDATE_REMAP && process.env.NXEON_CONSOLIDATE_REMAP !== "0";
475	  if (pathBlk.length && !remapEnabled) {
476	    return { error: `These servers overlap on paths (${ex(pathBlk)}). Path auto-remap is behind NXEON_CONSOLIDATE_REMAP until it's validated on a rehearsal — enable it, migrate the overlapping ones one at a time, or change them at the source.`, blockers, plan };
477	  }
478	
479	  // Hand each source to the normal migration path (the serial worker sequences the
480	  // jobs so imports don't race), carrying that source's path remap in items.
481	  const labels = input.sources.map((s, i) => String(s.label || s.sourceHost || `src-${i + 1}`).slice(0, 40));
482	  const ids: string[] = [];
483	  for (let i = 0; i < input.sources.length; i++) {
484	    const s = input.sources[i];
485	    const pathRemap: Record<string, string> = {};
486	    for (const rm of plan.remaps) if (rm.sourceLabel === labels[i] && rm.path) pathRemap[rm.path.from] = rm.path.to;
487	    const res = await createMigration({ ...s, serverId: input.serverId, pathRemap: Object.keys(pathRemap).length ? pathRemap : undefined });
488	    if (res.error) return { error: `Source ${s.sourceHost}: ${res.error}`, ids, plan };
489	    if (res.id) ids.push(res.id);
490	  }
491	  return { ids, plan };
492	}
