494	function toRow(
495	  m: {
496	    id: string;
497	    serverId: string;
498	    sourceHost: string;
499	    sourcePort: number;
500	    sourceUser: string;
501	    items: unknown;
502	    status: string;
503	    progress: number;
504	    step: string | null;
505	    log: string | null;
506	    lastError: string | null;
507	    createdAt: Date;
508	    finishedAt: Date | null;
509	  },
510	  server: { hostname: string; label: string | null } | null
511	): MigrationRow {
512	  const items = (m.items ?? {}) as {
513	    paths?: string[];
514	    databases?: { engine?: string; name?: string; user?: string }[];
515	    dbEngines?: string[];
516	  };
517	  // Databases are now auto-included per detected engine (no per-DB list). For the
518	  // client view, surface one row per engine; fall back to any legacy per-DB list.
519	  const dbView: MigrationDatabaseView[] =
520	    Array.isArray(items.databases) && items.databases.length
521	      ? items.databases.map((d) => ({
522	          engine: String(d.engine ?? ""),
523	          name: String(d.name ?? ""),
524	          user: String(d.user ?? ""),
525	        }))
526	      : Array.isArray(items.dbEngines)
527	        ? items.dbEngines.map((e) => ({ engine: String(e), name: "All databases", user: "root" }))
528	        : [];
529	  return {
530	    id: m.id,
531	    serverId: m.serverId,
532	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
533	    // caller resolves the server row and passes it in.
534	    serverName: server ? server.label || server.hostname : null,
535	    sourceHost: m.sourceHost,
536	    sourcePort: m.sourcePort,
537	    sourceUser: m.sourceUser,
538	    paths: Array.isArray(items.paths) ? items.paths : [],
539	    // Never expose any DB secret — dbView carries only non-sensitive fields.
540	    databases: dbView,
541	    status: m.status,
542	    progress: m.progress,
543	    step: m.step,
544	    log: m.log,
545	    lastError: m.lastError,
546	    createdAt: m.createdAt.toISOString(),
547	    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
548	  };
