553	/**
554	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
555	 * ownership, validates the source connection details, encrypts every source
556	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
557	 * the new migration id; never returns any secret.
558	 */
559	export async function createMigration(
560	  input: CreateMigrationInput
561	): Promise<{ error?: string; id?: string }> {
562	  const { user, server } = await ownedTargetServer(input.serverId);
563	
564	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
565	  // credential-stuffing the wizard against arbitrary source hosts.
566	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
567	  if (!rl.ok) {
568	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
569	  }
570	
571	  // Same public-address gate as scanSource — the worker will SSH here.
572	  const vetted = await vettedSourceHost(input.sourceHost);
573	  if ("error" in vetted) return { error: vetted.error };
574	  const host = vetted.host;
575	
576	  const port = input.sourcePort ?? 22;
577	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
578	    return { error: "SSH port must be between 1 and 65535." };
579	  }
580	
581	  const sourceUser = (input.sourceUser ?? "root").trim();
582	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
583	    return { error: "Enter the SSH username on the source server." };
584	  }
585	
586	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
587	    return { error: "Enter the SSH password for the source server." };
588	  }
589	
590	  const paths = cleanPaths(input.paths);
591	
592	  // Derive the passwordless lift-and-shift plan from the scan + selected paths.
593	  // Databases are auto-included when an engine is detected — no DB password is
594	  // ever collected; the worker dumps via root's local socket/peer auth.
595	  const plan = derivePlan(input.scan, paths);
596	
597	  // Persist the (secret-free) detection snapshot alongside the plan so the
598	  // migration is traceable back to what auto-detection found. Reusing items
599	  // avoids a schema change (Migration.items is a Json column).
600	  const scanSnapshot =
601	    input.scan && input.scan.ok
602	      ? {
603	          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
604	          homes: input.scan.homes?.slice(0, 40) ?? [],
605	          databases: input.scan.databases?.slice(0, 60) ?? [],
606	          engines: input.scan.engines ?? [],
607	          // Exact engine variant + version — lets the worker install the MATCHING
608	          // engine on the target for a clean same-engine restore.
609	          dbEngines: input.scan.dbEngines ?? [],
610	          // Running-app discovery — informational, secret-free, for traceability.
611	          appDirs: input.scan.appDirs?.slice(0, 40) ?? [],
612	          containers: input.scan.containers?.slice(0, 30) ?? [],
613	          ports: input.scan.ports?.slice(0, 60) ?? [],
614	          services: input.scan.services?.slice(0, 30) ?? [],
615	          // Storage-guardrail + compatibility inputs (secret-free, for traceability
616	          // and the worker pre-flight).
617	          dbSizeBytes: Math.max(0, input.scan.dbSizeBytes ?? 0),
618	          sourceOs: input.scan.sourceOs ?? null,
619	          sourceArch: input.scan.sourceArch ?? null,
620	          synthetic: !!input.scan.synthetic,
621	        }
622	      : undefined;
623	
624	  // Trusted server-side total of what will be migrated (bytes) — carried through
625	  // items so the worker's pre-flight guard can compare it to target free disk
626	  // without re-scanning. No schema change: Migration.items is a Json column.
627	  const totalBytes = selectedMigrationBytes(input.scan, paths);
628	
629	  const items = {
630	    paths,
631	    dbEngines: plan.dbEngines,
632	    dockerVolumes: plan.dockerVolumes,
633	    composeDirs: plan.composeDirs,
634	    verifyPorts: plan.verifyPorts,
635	    hasContainers: plan.hasContainers,
636	    webServers: plan.webServers,
637	    runtimes: plan.runtimes,
638	    totalBytes,
639	    // Explicit consent only — coerced to a real boolean so nothing else can ride
640	    // in on this field, and only ever true when the customer ticked the box.
641	    useVolumeForDocker: input.useVolumeForDocker === true,
642	    // Consolidation only: source→target path remap so a colliding path lands in
643	    // its own dir instead of overwriting an earlier source. Absent on normal runs.
644	    ...(input.pathRemap && Object.keys(input.pathRemap).length ? { remap: { paths: input.pathRemap } } : {}),
645	    // Per-migration SAFETY opt-ins. Only written when the caller supplies them, so
646	    // an omitted `options` leaves items.options undefined and the worker uses the
647	    // env-flag fallback (behaves exactly as before). Each field is coerced to a
648	    // strict boolean and defaults OFF so nothing else can ride in and no safety
649	    // default is weakened.
650	    ...(input.options
651	      ? {
652	          options: {
653	            overwriteTargetData: input.options.overwriteTargetData === true,
654	            renameClones: input.options.renameClones === true,
655	            copySshKeys: input.options.copySshKeys === true,
656	          },
657	        }
658	      : {}),
659	    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
660	  };
661	
662	  const migration = await db.migration.create({
663	    data: {
664	      userId: user.id,
665	      serverId: server.id,
666	      sourceHost: host,
667	      sourcePort: port,
668	      sourceUser,
669	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
670	      items,
671	      status: "PENDING",
672	      progress: 0,
673	      step: "Queued",
674	    },
675	  });
676	
677	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
678	  // traceability); the handler loads everything else from payload.migrationId.
679	  await db.job.create({
680	    data: {
681	      type: "MIGRATE",
682	      serverId: server.id,
683	      payload: { migrationId: migration.id },
684	    },
685	  });
686	
687	  await db.auditLog.create({
688	    data: {
689	      userId: user.id,
690	      action: "migration.create",
691	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${plan.dbEngines.length} db engine(s), ${plan.composeDirs.length} compose)`,
692	    },
693	  });
694	
695	  revalidatePath("/dashboard/migrate");
696	  return { id: migration.id };
697	}
