699	/**
700	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
701	 * caller owns the TARGET server (authz + a stricter rate limit than create),
702	 * validates the source connection details, then SSHes into the source and
703	 * inventories web roots / home directories / databases — never writing anything
704	 * on the source and never persisting the supplied credentials.
705	 *
706	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
707	 * are NOT stored anywhere; the client re-supplies them to createMigration once
708	 * the customer confirms what to move. Returns a secret-free ScanResult.
709	 *
710	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
711	 * a real SSH connection, so staging stays fully self-contained.
712	 */
713	export async function scanSource(input: {
714	  serverId: string;
715	  sourceHost: string;
716	  sourcePort?: number;
717	  sourceUser?: string;
718	  sourcePassword: string;
719	  dbUser?: string;
720	  dbPassword?: string;
721	}): Promise<{ error?: string; scan?: ScanResult; sizing?: SizingVerdict }> {
722	  const { user, server } = await ownedTargetServer(input.serverId);
723	  const targetPlan = server.planId
724	    ? await db.plan.findUnique({ where: { id: server.planId }, select: { ramMB: true } })
725	    : null;
726	  const sizingFor = (scan: ScanResult): SizingVerdict =>
727	    recommendPlanSizing({
728	      sourceMemMB: scan.sourceMemMB,
729	      sourceMemUsedMB: scan.sourceMemUsedMB,
730	      containerCount: scan.containers?.length,
731	      targetRamMB: targetPlan?.ramMB ?? 0,
732	    });
733	
734	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
735	  // than migration creation to stop the wizard being used to probe hosts.
736	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
737	  if (!rl.ok) {
738	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
739	  }
740	
741	  // Refuse private / loopback / reserved targets BEFORE anything is logged or
742	  // connected to. See vettedSourceHost: without this the wizard is an internal
743	  // port scanner and SSH credential-stuffer aimed at every other customer's VM.
744	  const vetted = await vettedSourceHost(input.sourceHost);
745	  if ("error" in vetted) return { error: vetted.error };
746	  const host = vetted.host;
747	  const port = input.sourcePort ?? 22;
748	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
749	    return { error: "SSH port must be between 1 and 65535." };
750	  }
751	  const sourceUser = (input.sourceUser ?? "root").trim();
752	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
753	    return { error: "Enter the SSH username on the source server." };
754	  }
755	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
756	    return { error: "Enter the SSH password for the source server." };
757	  }
758	
759	  await db.auditLog.create({
760	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
761	  }).catch(() => {});
762	
763	  // SANDBOX: never touch the outside world — hand back synthetic detection.
764	  if (SANDBOX) {
765	    const scan = syntheticScan({ dbPassword: input.dbPassword });
766	    return { scan, sizing: sizingFor(scan) };
767	  }
768	
769	  // Hard overall timeout so a slow/hostile source can't hang the request.
770	  const HARD_TIMEOUT_MS = 90_000;
771	  try {
772	    const scan = await Promise.race<ScanResult>([
773	      detectSource({
774	        // The ADDRESS we vetted, not the name — a name can resolve public for
775	        // our check and private for the connect (DNS rebinding).
776	        host: vetted.address,
777	        port,
778	        user: sourceUser,
779	        password: input.sourcePassword,
780	        dbUser: input.dbUser?.trim() || undefined,
781	        dbPassword: input.dbPassword || undefined,
782	      }),
783	      new Promise<ScanResult>((_, reject) =>
784	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
785	      ),
786	    ]);
787	    return { scan, sizing: sizingFor(scan) };
788	  } catch (e: any) {
789	    const msg = `${e?.message ?? e}`;
790	    // Map the common connection failures to friendly, non-leaky copy.
791	    if (/authentication|denied|password/i.test(msg)) {
792	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
793	    }
794	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
795	      return { error: "Couldn't reach the source server — check the host and SSH port." };
796	    }
797	    return { error: "We couldn't scan that server. Double-check the details and try again." };
798	  }
799	}
