801	// ---- Target free-space + OS probe (storage & compatibility guardrails) ------
802	
803	export type TargetInfo = {
804	  /** null when the server is unreachable / df couldn't be parsed → soft warning. */
805	  disk: { totalBytes: number; usedBytes: number; availBytes: number } | null;
806	  os: { id: string; versionId: string; pretty: string } | null;
807	  arch: string | null;
808	  /**
809	   * Capacity of the LARGEST attached-but-unformatted block device (a volume the
810	   * customer added but hasn't used yet), or null if there isn't one.
811	   *
812	   * This is capacity that is available **only if the customer chooses to use it**
813	   * — the engine can format it and relocate the container stores onto it, but it
814	   * never does so on its own (see `useVolumeForDocker`). Volumes are portable
815	   * add-on storage, and mounting a system path on one makes it undetachable, so
816	   * the wizard presents this as an opt-in, not as free space.
817	   *
818	   * The LARGEST, not the sum: separate volumes are separate filesystems and the
819	   * engine uses exactly one. They are deliberately never combined into an LVM
820	   * pool — that would weld them together and destroy the portability of all of
821	   * them at once.
822	   */
823	  spareDiskBytes?: number | null;
824	  /**
825	   * How many unused volumes are attached. 2+ means the panel should say that only
826	   * the largest can be used, so the customer isn't left expecting them to add up.
827	   */
828	  spareDiskCount?: number | null;
829	};
830	
831	/**
832	 * Probe a destination Nxeon server (owner-only) for its root-filesystem free
833	 * space and OS/architecture, so the wizard can show the storage headroom and the
834	 * OS-compatibility guardrail. Read-only: `df -B1`, `uname -m`, and a grep of
835	 * `/etc/os-release`. In SANDBOX returns synthetic values (never opens SSH).
836	 *
837	 * Failure is graceful: if the server is unreachable or df can't be parsed we
838	 * return `disk: null` (the UI shows "couldn't read free space" and allows the
839	 * migration with a soft warning rather than a hard block). OS falls back to the
840	 * server's known OS template; arch defaults to x86_64 (all our VMs are x86_64).
841	 */
842	export async function targetDiskFree(
843	  serverId: string
844	): Promise<{ error?: string; info?: TargetInfo }> {
845	  const { server } = await ownedTargetServer(serverId);
846	
847	  // OS fallback from the known OS template (works even if the box is unreachable).
848	  const tmpl = await db.osTemplate
849	    .findUnique({ where: { id: server.osTemplateId }, select: { family: true, version: true, name: true } })
850	    .catch(() => null);
851	  const osFallback = tmpl
852	    ? {
853	        id: (tmpl.family || "linux").toLowerCase(),
854	        versionId: tmpl.version || "",
855	        pretty: `${tmpl.name}${tmpl.version ? ` ${tmpl.version}` : ""}`,
856	      }
857	    : null;
858	
859	  if (SANDBOX) {
860	    // Synthetic 80 GB disk with ~63 GB free, matching our default plan sizing.
861	    return {
862	      info: {
863	        disk: { totalBytes: 80 * GiB, usedBytes: 17 * GiB, availBytes: 63 * GiB },
864	        os: osFallback ?? { id: "ubuntu", versionId: "24.04", pretty: "Ubuntu 24.04 LTS" },
865	        arch: "x86_64",
866	      },
867	    };
868	  }
869	
870	  // Need dedicatedIp to compute the SSH connection target (dedicated → :22).
871	  const full = await db.server.findUnique({
872	    where: { id: server.id },
873	    include: { dedicatedIp: true },
874	  });
875	
876	  try {
877	    const info = await withServerSsh(full as any, async (conn) => {
878	      // Root filesystem size/used/avail in bytes.
879	      const dfr = await exec(
880	        conn,
881	        "df -B1 --output=size,used,avail / 2>/dev/null | tail -n1",
882	        QUICK_TIMEOUT_MS
883	      );
884	      const nums = (dfr.stdout || "").trim().split("\n").pop()?.trim().split(/\s+/).map(Number) ?? [];
885	      let disk: TargetInfo["disk"] = null;
886	      if (nums.length >= 3 && nums.slice(0, 3).every((n) => Number.isFinite(n) && n > 0)) {
887	        disk = { totalBytes: nums[0], usedBytes: nums[1], availBytes: nums[2] };
888	      }
889	      const un = await exec(conn, "uname -m 2>/dev/null", QUICK_TIMEOUT_MS).catch(() => ({ stdout: "" }) as any);
890	      const arch = ((un.stdout as string) || "").trim().replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32) || null;
891	      const osr = await exec(
892	        conn,
893	        "grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null || true",
894	        QUICK_TIMEOUT_MS
895	      ).catch(() => ({ stdout: "" }) as any);
896	      const os = parseOsRelease((osr.stdout as string) || "") ?? osFallback;
897	      // Attached-but-unformatted disks (unused volumes the customer added).
898	      // Read-only probe, and it mirrors the engine's qualification bar exactly so
899	      // the panel can never promise space the engine would refuse to touch: a
900	      // disk counts only when nothing in its tree has a filesystem or mount, it
901	      // has no children, nothing holds it, `blkid` finds no signature at all,
902	      // and it is at least the engine's 4 GiB floor.
903	      let spareDiskBytes: number | null = null;
904	      let spareDiskCount: number | null = null;
905	      try {
906	        const lb = await exec(
907	          conn,
908	          "for d in $(lsblk -dn -o NAME,TYPE 2>/dev/null | awk '$2==\"disk\"{print $1}'); do " +
909	            "[ -n \"$(lsblk -n -o FSTYPE,MOUNTPOINT /dev/$d 2>/dev/null | tr -d ' \\n')\" ] && continue; " +
910	            "[ -n \"$(lsblk -no NAME /dev/$d 2>/dev/null | tail -n +2)\" ] && continue; " +
911	            "[ -n \"$(ls -A /sys/block/$d/holders 2>/dev/null)\" ] && continue; " +
912	            "blkid /dev/$d >/dev/null 2>&1 && continue; " +
913	            "sz=$(lsblk -bdn -o SIZE /dev/$d 2>/dev/null | tr -d ' '); " +
914	            "[ -z \"$sz\" ] && continue; " +
915	            "[ \"$sz\" -ge 4294967296 ] 2>/dev/null && echo \"$sz\"; done",
916	          QUICK_TIMEOUT_MS
917	        );
918	        const sizes = ((lb.stdout as string) || "")
919	          .split("\n")
920	          .map((s) => Number(s.trim()))
921	          .filter((n) => Number.isFinite(n) && n > 0);
922	        if (sizes.length) {
923	          // The LARGEST, never the sum — the engine uses exactly one volume and
924	          // does not combine them, so summing would promise space that no single
925	          // filesystem will ever have. The count lets the panel say so plainly.
926	          spareDiskCount = sizes.length;
927	          spareDiskBytes = Math.max(...sizes);
928	        }
929	      } catch {
930	        /* best-effort: absence just means we report root-only free space */
931	      }
932	      return { disk, os, arch: arch ?? "x86_64", spareDiskBytes, spareDiskCount };
933	    });
934	    return { info };
935	  } catch {
936	    // Unreachable / probe error → soft warning (no hard block).
937	    return { info: { disk: null, os: osFallback, arch: "x86_64" } };
938	  }
939	}
