999	/**
1000	 * Candidate domains to point at the migration's target server, cheapest source
1001	 * first. Ownership-checked (the migration must be the caller's).
1002	 *
1003	 *   1. `Domain` rows — domains the customer registered with us.
1004	 *   2. Websites already configured on the target server.
1005	 *   3. Hostnames inferable from the STORED scan snapshot (`Migration.items.scan`)
1006	 *      — web-root folders are conventionally named after the vhost. The snapshot
1007	 *      does not record nginx/apache `server_name` values, so this is a best-effort
1008	 *      read of what was already captured; we never re-scan the source.
1009	 */
1010	export async function getMigrationDnsInfo(migrationId: string): Promise<MigrationDnsInfo> {
1011	  const user = await requireUser();
1012	
1013	  const m = await db.migration.findUnique({ where: { id: migrationId } });
1014	  if (!m) return { error: "Migration not found." };
1015	  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." };
1016	
1017	  const server = await db.server.findUnique({
1018	    where: { id: m.serverId },
1019	    select: { hostname: true, label: true, ipAddress: true, dedicatedIp: { select: { address: true } } },
1020	  });
1021	
1022	  const seen = new Set<string>();
1023	  const candidates: DnsCandidate[] = [];
1024	  const push = (raw: string | null | undefined, source: DnsCandidate["source"]) => {
1025	    const host = cleanHostname(raw ?? "");
1026	    if (!host || seen.has(host)) return;
1027	    seen.add(host);
1028	    candidates.push({ host, source });
1029	  };
1030	
1031	  const domains = await db.domain.findMany({
1032	    where: { userId: m.userId },
1033	    select: { name: true },
1034	    orderBy: { name: "asc" },
1035	    take: 50,
1036	  });
1037	  for (const d of domains) push(d.name, "registered");
1038	
1039	  const sites = await db.website.findMany({
1040	    where: { serverId: m.serverId },
1041	    select: { domain: true },
1042	    take: 50,
1043	  });
1044	  for (const s of sites) push(s.domain, "website");
1045	
1046	  // Only what the scan already stored — no new source-scanning here.
1047	  const items = (m.items ?? {}) as { scan?: { webRoots?: { path?: string }[] } };
1048	  for (const w of items.scan?.webRoots ?? []) {
1049	    if (w?.path) push(hostnameFromPath(w.path), "scan");
1050	  }
1051	
1052	  return {
1053	    targetIp: server?.dedicatedIp?.address ?? server?.ipAddress ?? null,
1054	    targetName: server ? server.label || server.hostname : null,
1055	    candidates: candidates.slice(0, 40),
1056	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
