1116	// ---- Post-migration remediation (Layer 2) ----------------------------------
1117	// A migration finishes COMPLETED_WITH_ISSUES when a source domain does not serve
1118	// on the new server yet — usually because an app did not auto-start. Rather than
1119	// leaving the customer to SSH in, the PLATFORM (which holds root SSH to the
1120	// target) finishes it on their behalf, over its own connection, from a button.
1121	//
1122	// These are TARGET-side only: the source password is cleared once a migration
1123	// ends, so re-pulling from the source is out of scope here (that needs a
1124	// reconnect flow). What they DO cover is the common case — bring up copied
1125	// compose stacks, start the units the engine created, reload nginx, and re-probe
1126	// each domain HONESTLY (a placeholder page is not "serving", per the #59 gate).
1127	
1128	const REMEDIATE_COMPOSE_FILES =
1129	  "docker-compose.yml docker-compose.yaml compose.yml compose.yaml docker-compose.prod.yml docker-compose.prod.yaml docker-compose.production.yml compose.prod.yml compose.production.yml docker-compose.override.yml compose.override.yml";
1130	// The distribution placeholder pages that must never count as a live site.
1131	const PLACEHOLDER_RE =
1132	  /Apache2 Debian Default Page|Welcome to nginx|Test Page for the .* HTTP Server|Your IP address is/i;
1133	const REMEDIATE_PATH_RE = /^\/[A-Za-z0-9._/-]{1,255}$/;
1134	
1135	export type SiteServingView = { domain: string; serving: boolean; code: string };
1136	export type RemediationResult = {
1137	  error?: string;
1138	  ok?: boolean;
1139	  /** Domains that serve their real site now. */
1140	  serving?: string[];
1141	  /** Domains that still do not serve. */
1142	  dark?: string[];
1143	  /** Did the whole migration flip to fully-served (status → DONE)? */
1144	  allServing?: boolean;
1145	  /** Short human lines describing what the finish step did. */
1146	  log?: string[];
1147	};
