1149	async function ownedMigrationForRemediation(id: string) {
1150	  const user = await requireUser();
1151	  const m = await db.migration.findUnique({ where: { id } });
1152	  if (!m) return { error: "That migration no longer exists." as const };
1153	  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." as const };
1154	  const server = await db.server.findUnique({
1155	    where: { id: m.serverId },
1156	    select: {
1157	      id: true,
1158	      hostname: true,
1159	      rootPassword: true,
1160	      rootPasswordEnc: true,
1161	      sshPort: true,
1162	      dedicatedIp: { select: { address: true } },
1163	    },
1164	  });
1165	  if (!server) return { error: "The target server for this migration is gone." as const };
1166	  return { user, m, server };
