1169	/** The domains to re-check: what the source served, from the stored scan. */
1170	function migrationProbeDomains(items: unknown): string[] {
1171	  const scan = ((items ?? {}) as { scan?: { vhostDomains?: unknown[] } }).scan ?? {};
1172	  const out = new Set<string>();
1173	  for (const d of scan.vhostDomains ?? []) {
1174	    const h = cleanHostname(String(d ?? ""));
1175	    if (h) out.add(h);
1176	  }
1177	  return [...out].slice(0, 30);
1178	}
