1180	/**
1181	 * Ask the TARGET (over its own loopback, so no DNS is needed) what it serves for
1182	 * `domain`, and whether that is a real site or a placeholder. HTTPS is checked
1183	 * first (authoritative when a cert exists), then HTTP.
1184	 */
1185	async function probeDomainOnTarget(conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], domain: string): Promise<SiteServingView> {
1186	  if (!/^[a-z0-9.-]{1,253}$/.test(domain)) return { domain, serving: false, code: "000" };
1187	  const httpsCode = (
1188	    await exec(conn, `curl -sk -o /tmp/nxeon-probe -m 8 --resolve ${domain}:443:127.0.0.1 -w '%{http_code}' https://${domain}/ 2>/dev/null`, 15000)
1189	  ).stdout.trim().slice(0, 3);
1190	  let code = httpsCode;
1191	  if (!/^[1-9]\d\d$/.test(code)) {
1192	    code = (
1193	      await exec(conn, `curl -s -o /tmp/nxeon-probe -m 8 -H 'Host: ${domain}' -w '%{http_code}' http://127.0.0.1/ 2>/dev/null`, 15000)
1194	    ).stdout.trim().slice(0, 3);
1195	  }
1196	  const body = (await exec(conn, `head -c 4096 /tmp/nxeon-probe 2>/dev/null`, 10000)).stdout;
1197	  const serving = /^(2|3)\d\d$/.test(code) && !PLACEHOLDER_RE.test(body);
1198	  return { domain, serving, code: code || "000" };
1199	}
