1201	async function reprobeAndSettle(conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], domains: string[]): Promise<SiteServingView[]> {
1202	  const results = new Map<string, SiteServingView>();
1203	  for (const d of domains) results.set(d, await probeDomainOnTarget(conn, d));
1204	  return [...results.values()];
1205	}
