1207	async function persistServingOutcome(migrationId: string, currentStatus: string, probes: SiteServingView[]): Promise<boolean> {
1208	  const dark = probes.filter((p) => !p.serving);
1209	  const allServing = probes.length > 0 && dark.length === 0;
1210	  // Only ever UPGRADE the honest verdict — a re-check that finds everything live
1211	  // flips COMPLETED_WITH_ISSUES → DONE. Never downgrade (that belongs to the
1212	  // engine's own run, not a spot re-check).
1213	  if (allServing && currentStatus === "COMPLETED_WITH_ISSUES") {
1214	    await db.migration.update({
1215	      where: { id: migrationId },
1216	      data: { status: "DONE", step: "Completed — all sites serving" },
1217	    }).catch(() => {});
1218	  }
1219	  return allServing;
1220	}
