1222	/**
1223	 * Re-check (only) whether each site serves now, and flip the migration to DONE
1224	 * if they all do. No bring-up — just an honest re-probe. Cheap; safe to spam.
1225	 */
1226	export async function recheckMigrationServing(migrationId: string): Promise<RemediationResult> {
1227	  const ctx = await ownedMigrationForRemediation(migrationId);
1228	  if ("error" in ctx) return { error: ctx.error };
1229	  const { m, server, user } = ctx;
1230	  const rl = checkRateLimit(`migrate:recheck:${user.id}`, { max: 20, windowMs: 5 * 60 * 1000 });
1231	  if (!rl.ok) return { error: `Please wait ${rl.retryAfterSec}s before checking again.` };
1232	  const domains = migrationProbeDomains(m.items);
1233	  if (!domains.length) return { ok: true, serving: [], dark: [], allServing: false, log: ["No domains to check."] };
1234	  if (SANDBOX) {
1235	    return { ok: true, serving: domains, dark: [], allServing: true, log: ["Sandbox: pretended all sites serve."] };
1236	  }
1237	  try {
1238	    const probes = await withServerSsh(server, (conn) => reprobeAndSettle(conn, domains));
1239	    const allServing = await persistServingOutcome(m.id, m.status, probes);
1240	    revalidatePath("/dashboard/migrate");
1241	    return {
1242	      ok: true,
1243	      serving: probes.filter((p) => p.serving).map((p) => p.domain),
1244	      dark: probes.filter((p) => !p.serving).map((p) => p.domain),
1245	      allServing,
1246	    };
1247	  } catch {
1248	    return { error: "Couldn't reach the new server to check. Try again in a moment." };
1249	  }
1250	}
