1252	/**
1253	 * Finish the migration the customer couldn't: bring up any copied compose stacks,
1254	 * start the units the engine created (incl. the reproduced pm2/manual-start
1255	 * apps), reload nginx, then re-probe. Everything here is idempotent and
1256	 * TARGET-side; it never touches the old server and never removes anything.
1257	 */
1258	export async function finishMigrationSetup(migrationId: string): Promise<RemediationResult> {
1259	  const ctx = await ownedMigrationForRemediation(migrationId);
1260	  if ("error" in ctx) return { error: ctx.error };
1261	  const { m, server, user } = ctx;
1262	  const rl = checkRateLimit(`migrate:finish:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
1263	  if (!rl.ok) return { error: `Please wait ${rl.retryAfterSec}s before trying again.` };
1264	  const domains = migrationProbeDomains(m.items);
1265	  const composeDirs = (((m.items ?? {}) as { composeDirs?: unknown[] }).composeDirs ?? [])
1266	    .map((p) => String(p ?? ""))
1267	    .filter((p) => REMEDIATE_PATH_RE.test(p))
1268	    .slice(0, 20);
1269	  if (SANDBOX) {
1270	    return { ok: true, serving: domains, dark: [], allServing: true, log: ["Sandbox: pretended to finish setup."] };
1271	  }
1272	  const log: string[] = [];
1273	  try {
1274	    await withServerSsh(server, async (conn) => {
1275	      // 1. Bring up copied compose stacks (idempotent; -f for non-default names).
1276	      for (const dir of composeDirs) {
1277	        const cf = (
1278	          await exec(conn, `for f in ${REMEDIATE_COMPOSE_FILES}; do [ -f ${dir}/$f ] && { echo ${dir}/$f; break; }; done`, 15000)
1279	        ).stdout.trim();
1280	        if (!REMEDIATE_PATH_RE.test(cf)) continue;
1281	        const fArg = /\/(docker-compose|compose)\.ya?ml$/.test(cf) ? "" : `-f ${cf} `;
1282	        const r = await exec(conn, `sh -c 'cd ${dir} && docker compose ${fArg}up -d' 2>&1 | tail -2`, 300000);
1283	        log.push(`Started ${dir.split("/").pop()}: ${r.stdout.trim().slice(0, 100) || "ok"}`);
1284	      }
1285	      // 2. Start the units the engine created that aren't running yet.
1286	      await exec(
1287	        conn,
1288	        `for u in $(systemctl list-unit-files 'nxeon-app-*.service' --no-legend 2>/dev/null | awk '{print $1}'); do systemctl start "$u" 2>/dev/null || true; done`,
1289	        60000
1290	      );
1291	      // 3. Reload nginx if its config is valid.
1292	      await exec(conn, `nginx -t >/dev/null 2>&1 && systemctl reload nginx 2>/dev/null || true`, 30000);
1293	      log.push("Reloaded the web server.");
1294	    });
1295	    // 4. Give the just-started apps a moment, then probe honestly.
1296	    await new Promise((r) => setTimeout(r, 12000));
1297	    const probes = await withServerSsh(server, (conn) => reprobeAndSettle(conn, domains));
1298	    const allServing = await persistServingOutcome(m.id, m.status, probes);
1299	    revalidatePath("/dashboard/migrate");
1300	    return {
1301	      ok: true,
1302	      serving: probes.filter((p) => p.serving).map((p) => p.domain),
1303	      dark: probes.filter((p) => !p.serving).map((p) => p.domain),
1304	      allServing,
1305	      log,
1306	    };
1307	  } catch {
1308	    return { error: "Couldn't finish setup on the new server. Your old server is still serving — try again shortly." };
1309	  }
1310	}
