278	export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
279	  const user = await requireUser();
280	
281	  // --- Staff-only: read COMPANY mailboxes (admin@, support@, …) in-portal. ---
282	  // This is an ADDITIVE branch: it only runs for staff, so the customer
283	  // resolution below is completely unchanged. A company mailbox is synthesized
284	  // into the same ResolvedMailbox shape (no EmailSubscription backing it).
285	  if (isStaff(user.role)) {
286	    const wantedLc = mailboxAddress?.trim().toLowerCase();
287	    const synthesize = (c: {
288	      id: string;
289	      address: string;
290	      label: string | null;
291	      passwordEnc: string;
292	      quotaMB: number;
293	      status: string;
294	    }): ResolvedMailbox => {
295	      const password = decryptSecret(c.passwordEnc);
296	      if (!password) throw new Error("Reset this mailbox's password to enable webmail access.");
297	      return {
298	        user,
299	        mailboxId: `company:${c.id}`,
300	        address: c.address,
301	        quotaMB: c.quotaMB,
302	        cred: { address: c.address, password },
303	        identity: { displayName: c.label, replyTo: null, organization: null },
304	        subscription: {
305	          id: `company:${c.id}`,
306	          domainName: COMPANY_MAIL_DOMAIN,
307	          external: false,
308	          verified: true,
309	          status: c.status,
310	        },
311	      };
312	    };
313	    // Only resolve an EXPLICITLY requested company address (the admin inbox always
314	    // passes one). With no address, fall through to the customer path — so a
315	    // staffer's own /dashboard/mail never silently lands on a company mailbox.
316	    if (wantedLc) {
317	      const c = await db.companyMailbox.findUnique({ where: { address: wantedLc } });
318	      if (c) return synthesize(c);
319	      // Not a company address — fall through to the customer path below.
320	    }
321	  }
322	
323	  const load = () =>
324	    db.mailbox.findMany({
325	      where: { subscription: { userId: user.id } },
326	      include: { subscription: true },
327	      orderBy: { createdAt: "asc" },
328	    });
329	
330	  let boxes = await load();
